sheet.css:
.pk{--felt:#8e8e95;--ink:#1e1e22;--muted:#5a5a62;--pt:#f2f2f4;--pb:#d9d9db;--edge:#9a9aa0;--led:#25d366;
  --chassis:#d9d9db;--chi:#f2f2f4;--chlo:#c2c2c6;--accent:#d93a1e;
  background-color:var(--felt);
  background-image:linear-gradient(rgba(255,255,255,.10),rgba(0,0,0,.16)),
    repeating-linear-gradient(45deg,rgba(0,0,0,.03) 0 2px,transparent 2px 4px);
  color:var(--ink);font:500 15px/1.5 ui-sans-serif,system-ui,-apple-system,sans-serif}
[data-theme=dark] .legend{color:#c2c2cc}
[data-theme=dark].pk,[data-theme=dark] .pk{--felt:#17171a;--ink:#e9e9ee;--muted:#a6a6b0;
  --pt:#3a3a40;--pb:#26262b;--edge:#4a4a52;--chassis:#2b2b30;--chi:#3d3d44;--chlo:#202024}
.stage.pk{background-color:var(--felt)}
.pk h3,.pk h4{margin:0;font-weight:700;text-shadow:0 1px 0 rgba(255,255,255,.5)}
[data-theme=dark] .pk h3,[data-theme=dark] .pk h4{text-shadow:0 1px 0 rgba(0,0,0,.5)}
.pk p{margin:0}
.panel{background:linear-gradient(var(--pt) 0%,var(--pb) 48%,#d8ccb0 52%,var(--pt) 100%);
  border:1px solid var(--edge);border-radius:12px;padding:18px;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.85),0 2px 3px rgba(0,0,0,.35),0 6px 12px rgba(0,0,0,.22)}
.stitch{border:2px dashed #a8a8b0;border-radius:6px;padding:12px;font-style:italic}
.pk-btn{font:700 14px/1 ui-sans-serif,system-ui;color:#1e1e22;padding:12px 22px;border:1px solid var(--edge);
  border-radius:8px;cursor:pointer;
  background:linear-gradient(#fafafb 0%,#e6e6ea 48%,#d2d2d8 52%,#eeeef1 100%);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.85),inset 0 -1px 0 rgba(0,0,0,.18),
    0 2px 3px rgba(0,0,0,.35),0 6px 12px rgba(0,0,0,.22);
  text-shadow:0 1px 0 rgba(255,255,255,.7);transition:box-shadow .06s,transform .06s}
.pk-btn:hover{background:linear-gradient(#fff 0%,#f0f0f3 48%,#dcdce2 52%,#f6f6f8 100%)}
.pk-btn:active,.f-active{box-shadow:inset 0 2px 5px rgba(0,0,0,.4);transform:translateY(1px)}
.pk-btn:focus-visible{outline:3px solid #2f6fd0;outline-offset:2px}
.pk-btn[disabled]{color:#8a7d63;cursor:not-allowed;box-shadow:inset 0 1px 0 rgba(255,255,255,.5)}
.f-hover{background:linear-gradient(#fff 0%,#f0f0f3 48%,#dcdce2 52%,#f6f6f8 100%)!important}
.f-focus{outline:3px solid #2f6fd0;outline-offset:2px}
.pk-field{width:100%;font:500 15px/1.2 ui-sans-serif,system-ui;color:var(--ink);border:1px solid var(--edge);
  border-radius:7px;padding:10px 12px;background:#e2e2e6;
  box-shadow:inset 0 2px 5px rgba(0,0,0,.28),inset 0 -1px 0 rgba(255,255,255,.7)}
.pk-field:focus-visible{outline:3px solid #2f6fd0;outline-offset:2px}
.pk-label{display:block;font-weight:700;font-size:13px;margin-bottom:6px;
  text-shadow:0 1px 0 rgba(255,255,255,.55)}
.pk-err{margin-top:8px;font-size:13px;font-weight:700;color:#8e2b12}
.pk-nav{display:flex;gap:4px;align-items:center;padding:8px;border-radius:10px;
  background:linear-gradient(#eaeaee,#d4d4da);border:1px solid var(--edge);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.8),0 2px 3px rgba(0,0,0,.3)}
.pk-nav .brand{font-weight:700;padding:0 10px}
.pk-nav a{padding:8px 12px;border-radius:7px;color:var(--ink);text-decoration:none;font-weight:700;font-size:13px}
.pk-nav a[aria-current]{background:#c4c4ca;box-shadow:inset 0 2px 4px rgba(0,0,0,.35)}
.pk-nav .sp{flex:1}
table.pk-t{width:100%;border-collapse:collapse;font-size:14px}
table.pk-t th{text-align:left;font-weight:700;padding:0 10px 8px 0;
  border-bottom:2px solid var(--edge);text-shadow:0 1px 0 rgba(255,255,255,.5)}
table.pk-t td{padding:10px 10px 10px 0;border-bottom:1px solid rgba(0,0,0,.14);
  box-shadow:0 1px 0 rgba(255,255,255,.4)}
.pk-scrim{background:rgba(58,47,28,.66);padding:32px 18px;display:flex;justify-content:center;border-radius:12px}
.well{background:#c9c9ce;border-radius:10px;padding:22px;text-align:center;
  box-shadow:inset 0 2px 6px rgba(0,0,0,.4),0 1px 0 rgba(255,255,255,.5)}
.pk-skel{height:13px;background:#c9c9ce;border-radius:6px;margin-bottom:9px;
  box-shadow:inset 0 1px 3px rgba(0,0,0,.3)}
.led{width:12px;height:12px;border-radius:50%;
  background:radial-gradient(circle at 35% 30%,#9f9,#1a1);box-shadow:0 0 8px #4f4,inset 0 -1px 2px rgba(0,0,0,.5)}
.swatch{border:1px solid var(--edge,#8b7a56);border-radius:8px;height:54px;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.6),0 2px 3px rgba(0,0,0,.3)}
/* ── HARDWARE. The modern register for this style: knobs, faders, meters. ── */
.chassis{background:linear-gradient(var(--chi) 0%,var(--chassis) 48%,var(--chlo) 52%,var(--chi) 100%);
  border:1px solid #9a9aa0;border-radius:14px;padding:22px;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.9),inset 0 -1px 0 rgba(0,0,0,.18),
    0 2px 3px rgba(0,0,0,.35),0 10px 22px rgba(0,0,0,.28)}
.screw{width:9px;height:9px;border-radius:50%;background:radial-gradient(circle at 34% 30%,#fff,#9a9aa0);
  box-shadow:inset 0 -1px 1px rgba(0,0,0,.4);position:relative}
.screw::after{content:"";position:absolute;inset:3px 1px;border-top:1px solid rgba(0,0,0,.45)}

.knob{width:72px;height:72px;border-radius:50%;position:relative;
  background:linear-gradient(#3a3a40,#1b1b1f);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.28),0 2px 3px rgba(0,0,0,.5),0 7px 14px rgba(0,0,0,.32)}
.knob::after{content:"";position:absolute;left:50%;top:8px;width:3px;height:22px;margin-left:-1.5px;
  background:#f2f2f4;border-radius:2px;box-shadow:0 0 3px rgba(0,0,0,.5)}
.knob.r30::after{transform:rotate(30deg);transform-origin:50% 28px}
.knob.r-40::after{transform:rotate(-40deg);transform-origin:50% 28px}
.knob.accent{background:linear-gradient(#e8563a,#b62d13)}

.fader{width:38px;height:132px;border-radius:8px;background:#b6b6bb;position:relative;
  box-shadow:inset 0 2px 6px rgba(0,0,0,.45),0 1px 0 rgba(255,255,255,.7)}
.fader i{position:absolute;left:5px;right:5px;height:26px;border-radius:5px;
  background:linear-gradient(#4a4a52,#232329);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.3),0 2px 3px rgba(0,0,0,.5)}
.fader i::after{content:"";position:absolute;left:5px;right:5px;top:12px;height:2px;background:#c9c9cf}

.sw{width:52px;height:28px;border-radius:14px;background:#b6b6bb;position:relative;
  box-shadow:inset 0 2px 5px rgba(0,0,0,.42)}
.sw i{position:absolute;top:2px;left:2px;width:24px;height:24px;border-radius:50%;
  background:linear-gradient(#fff,#d2d2d8);box-shadow:0 2px 3px rgba(0,0,0,.4)}
.sw.on{background:#2f7a4a}.sw.on i{left:26px}

.meter{display:flex;gap:3px;align-items:flex-end;height:46px;padding:6px;border-radius:6px;
  background:#1b1b1f;box-shadow:inset 0 2px 6px rgba(0,0,0,.6)}
.meter b{width:7px;border-radius:1px;background:#25d366}
.meter b.hot{background:#e8b41e}.meter b.pk{background:#d93a1e}

.legend{font:700 10px/1 ui-sans-serif,system-ui;letter-spacing:.14em;text-transform:uppercase;
  color:#3f3f47;text-shadow:0 1px 0 rgba(255,255,255,.6)}
.accentpanel{background:linear-gradient(#e8563a,#c33318);border-radius:12px;padding:20px;color:#fff;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.35),0 2px 3px rgba(0,0,0,.4),0 10px 20px rgba(0,0,0,.28)}
.accentpanel .legend{color:#fff;text-shadow:0 1px 0 rgba(0,0,0,.3)}
